#include <cstdio>
#include <stack>

using namespace std;

int a[20];

bool check(int x) {
    int pre = 0;
    for (int i = 0; i < 10; i++) if (x & (1 << i)) {
        if (a[i] < pre) return false;
        pre = a[i];
    }
    return true;
}

bool dfs(int x) {
    stack<pair<int, int>> s; // Stack for iterative DFS
    s.push({1, x});
    int pre = a[0];

    while (!s.empty()) {
        auto [i, current] = s.top();
        s.pop();

        if (i == 10) {
            if (check(current)) return true;
            continue;
        }

        if (a[i] > pre) {
            s.push({i + 1, current}); // do not include a[i]
            s.push({i + 1, current | (1 << i)}); // include a[i]
        } else {
            s.push({i + 1, current | (1 << i)}); // include a[i]
        }
    }
    return false;
}

int main() {
    int T;
    scanf("%d", &T);
    while (T--) {
        for (int i = 0; i < 10; i++) scanf("%d", &a[i]);
        printf("%s\n", dfs(0) ? "YES" : "NO");
    }
    return 0;
}

